{'code': "from qgis.PyQt.QtWidgets import QAction, QMenu
mw = iface.mainWindow()
matches = []
for a in mw.findChildren(QAction):
    t = a.text().replace('&','')
    if '貼り付' in t or '貼付' in t or 'Paste' in a.objectName():
        parents = []
        try:
            for o in a.associatedObjects():
                if isinstance(o, QMenu):
                    parents.append('menu:' + (o.title() or o.objectName()))
                else:
                    parents.append(type(o).__name__)
        except Exception:
            pass
        matches.append({'objectName': a.objectName(), 'text': t, 'enabled': a.isEnabled(), 'visible': a.isVisible(), 'parents': parents})
lyr = iface.activeLayer()
info = {'activeLayer': lyr.name() if lyr else None, 'isEditable': lyr.isEditable() if lyr else None}
result = {'actions': matches, 'activeLayer': info}"}
